import{_ as i,c as r,o as t,ag as s}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Server Guides","description":"","frontmatter":{"title":"Server Guides"},"headers":[],"relativePath":"server-guides/index.md","filePath":"server-guides/index.md","lastUpdated":null}'),l={name:"server-guides/index.md"};function a(n,e,o,u,p,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="server-guides" tabindex="-1">Server Guides <a class="header-anchor" href="#server-guides" aria-label="Permalink to &quot;Server Guides&quot;">​</a></h1><h2 id="server-guides-1" tabindex="-1">Server Guides <a class="header-anchor" href="#server-guides-1" aria-label="Permalink to &quot;Server Guides&quot;">​</a></h2><h3 id="community-server-guides" tabindex="-1">Community Server Guides <a class="header-anchor" href="#community-server-guides" aria-label="Permalink to &quot;Community Server Guides&quot;">​</a></h3><ul><li><p><a href="/server-guides/mantrix-with-ansible.html">Server Guide</a></p><ul><li>Maubot Chatbot Guides</li></ul></li><li><p>SimpleX Server</p></li><li><p><a href="/privacy/service-storage-nextcloud.html">- Storage - Nextcloud</a></p></li><li><p><em>Installation</em></p></li><li><p><a href="/server-guides/setting-up-cryptpad-server.html">Up Cryptpad Server</a></p></li><li><p>Proxmox</p></li><li><p>Clapper</p></li><li><p><a href="/server-guides/linux-server-initial-setup.html">Server Initial Setup</a></p></li><li><p><a href="/server-guides/linux-server-storage.html">Server Storage</a></p></li></ul><h3 id="best-practices-to-secure-servers-in-2024" tabindex="-1">Best Practices to Secure Servers in 2024 <a class="header-anchor" href="#best-practices-to-secure-servers-in-2024" aria-label="Permalink to &quot;Best Practices to Secure Servers in 2024&quot;">​</a></h3><p>Source:</p><ul><li><p><a href="https://www.reddit.com/r/linuxadmin/comments/1an0vqp/best_practice_to_secure_servers_in_2024/" target="_blank" rel="noreferrer">Best practice to secure servers in 2024</a></p></li><li><p><a href="https://madaidans-insecurities.github.io/guides/linux-hardening.html" target="_blank" rel="noreferrer">Madaidans Insecurities Linux Hardening Guide</a></p></li><li><p><a href="https://www.cyberciti.biz/tips/linux-security.html" target="_blank" rel="noreferrer">Cyberciti Linux Security Tips</a></p></li></ul><h3 id="general-security-practices" tabindex="-1">General Security Practices <a class="header-anchor" href="#general-security-practices" aria-label="Permalink to &quot;General Security Practices&quot;">​</a></h3><ul><li><p><strong>No Root Login</strong>: Disable root login to enhance security.</p></li><li><p><strong><a href="/general/ssh-keys.html">Keys</a> with Password</strong>: Use SSH keys with a passphrase and disable password login.</p></li><li><p><strong>VPN Access</strong>: VPN access is required to reach the SSH server.</p></li><li><p><strong>Firmware and Auto Updates</strong>: Enable automatic updates for both firmware and software.</p></li><li><p><strong>Firewall</strong>: Configure a firewall to control incoming and outgoing traffic.</p></li><li><p><strong>Regular Updates</strong>: Ensure the server and all software are regularly updated.</p></li><li><p><strong>Split Disks</strong>: Separate <em>/tmp</em> and <em>/var</em> partitions with <em>noexec</em> flag.</p></li><li><p><strong>Log Monitoring</strong>: Regularly monitor server logs for suspicious activities.</p></li><li><p><strong>Privilege Escalation Mitigation</strong>: Use <em>sysctl</em> variables and kernel parameters to mitigate privilege escalation.</p></li><li><p><strong>Audit</strong>: Regularly audit the server using tools like <em>rkhunter</em> and <em>debsecan</em>.</p></li><li><p><strong>Open Ports</strong>: Only open necessary ports (e.g., 80, 443, 22).</p></li></ul><h3 id="detailed-security-measures" tabindex="-1">Detailed Security Measures <a class="header-anchor" href="#detailed-security-measures" aria-label="Permalink to &quot;Detailed Security Measures&quot;">​</a></h3><ul><li><p><strong>Data Encryption</strong>: Encrypt all data communication.</p><ul><li>Use <em>scp</em>, <em>ssh</em>, <em>rsync</em>, rclone or <em>sftp</em> for file transfer.</li><li>Consider reverse proxy (tail scale, Cloudflare) or wireguard.</li></ul></li><li><p><strong>Service Management</strong>:</p><ul><li>Avoid using insecure services like FTP, Telnet, and Rsh.</li><li>Minimize installed software to reduce vulnerability.</li></ul></li><li><p><strong>Kernel and Software Updates</strong>:</p><ul><li>Apply all security patches promptly. <ul><li>Use an Ansible Script to patch multiple servers periodically including OS, docker, git, etc</li></ul></li></ul></li><li><p><strong>Linux Security Extensions</strong>:</p><ul><li>Enable SELinux or other security extensions to enforce limitations on applications.</li></ul></li><li><p><strong>User Accounts and Password Policies</strong>:</p><ul><li>Enforce strong password policies.</li><li>Use tools like <em>pam_cracklib</em> to enforce password strength.</li><li>Set up password aging policies using <em>chage</em>.</li></ul></li><li><p><strong>Fail2ban</strong>:</p><ul><li>Install and configure Fail2ban to block IP addresses after failed login attempts.</li></ul></li><li><p><strong>Disable Unwanted Services</strong>:</p><ul><li>Disable unnecessary services and daemons.</li><li>Use <em>systemctl</em> to manage services on modern Linux distributions.</li></ul></li><li><p><strong>Network Security</strong>:</p><ul><li>Use <em>iptables</em> or <em>firewalld</em> to manage firewall rules.</li><li>Use tools like <em>nmap</em> to scan open ports.</li></ul></li><li><p><strong>File System Security</strong>:</p><ul><li>Separate critical file systems into different partitions with appropriate mount options (<em>noexec</em>, <em>nodev</em>, <em>nosuid</em>).</li></ul></li><li><p><strong>Regular Backups</strong>:</p><ul><li>Implement regular, encrypted backups to an offsite location.</li></ul></li><li><p><strong>Intrusion Detection Systems (IDS)</strong>:</p><ul><li>Use tools like AIDE and RKHunter for host-based intrusion detection.</li></ul></li><li><p><strong>Secure SSH Configuration</strong>:</p><ul><li>Configure SSH for maximum security (e.g., disabling root login, using SSH keys, configuring Fail2ban).</li></ul></li></ul>',11)])])}const m=i(l,[["render",a]]);export{g as __pageData,m as default};
